def main() -> None:
    md = RAIZ / "prompts-higgsfield.md"
    texto = md.read_text(encoding="utf-8")
    if "[SENHORA]" in texto:
        raise SystemExit("A seção de Nossa Senhora já está no prompts-higgsfield.md.")
    linhas = ["", "## Série Nossa Senhora (40 títulos, só figura)", "",
              "Trocar `[SENHORA]` pela coluna Figura:", "", "> " + BASE, "",
              "Ao conferir: os itens da coluna Conferir aparecem; sem texto nem letras; auréola só em Nossa Senhora, no Menino e nos santos que o título pede.", "",
              "| # | id | Título | Figura | Conferir | Objetos |", "|---|---|---|---|---|---|"]
    linhas += [f"| {301 + n} | {i} | {t} | {f} | {c} | - |" for n, (i, t, f, c) in enumerate(TITULOS)]
    md.write_text(texto.rstrip("\n") + "\n" + "\n".join(linhas) + "\n", encoding="utf-8")
    print(f"{len(TITULOS)} títulos acrescentados ao prompts-higgsfield.md")


if __name__ == "__main__":
    main()
